mapper.update:
UPDATE ccds_file_object
SET biz_type = #{bizType},
    gmt_modified = CURRENT_TIMESTAMP
WHERE id = #{id}
  AND biz_type = #{pendingBizType}

mapper.select:
SELECT id, biz_type, biz_id, cos_key, content_type,
       size_bytes, created_by, gmt_create, gmt_modified
FROM ccds_file_object
WHERE biz_type = #{bizType}
  AND biz_id = #{bizId}
ORDER BY gmt_create ASC

mapper.delete:
DELETE FROM ccds_file_object
WHERE biz_type IN (#{bizType}, CONCAT('P_', #{bizType}))
  AND biz_id = #{bizId}
